// MODE               : 'simulation' = les factures sont repérées et listées, RIEN n'est envoyé ni libellé.
//                      'reel'       = chaque PDF part vers Pennylane, puis le mail reçoit le libellé de traitement.
// ADRESSE_PENNYLANE  : adresse de collecte des factures fournisseurs (Pennylane → Paramètres → Factures fournisseurs).
// RECHERCHE_GMAIL    : ce qui désigne une facture fournisseur dans la boîte (syntaxe de recherche Gmail).
//                      Ex. 'label:factures-fournisseurs' ou '{from:edf.fr from:total.fr}'.
// LIBELLE_TRAITE     : nom du libellé posé après envoi, tel qu'écrit dans une recherche Gmail (tirets, sans espace).
// LIBELLE_TRAITE_ID  : identifiant du même libellé (Label_…), exigé par Gmail pour le poser.
// ANCIENNETE_JOURS   : on ne regarde pas les mails plus vieux que cela.
const reglages = {
  MODE: 'simulation',
  ADRESSE_PENNYLANE: '',
  RECHERCHE_GMAIL: 'label:factures-fournisseurs',
  LIBELLE_TRAITE: 'transmis-pennylane',
  LIBELLE_TRAITE_ID: '',
  ANCIENNETE_JOURS: 30,
};
if (reglages.MODE === 'reel' && (!reglages.ADRESSE_PENNYLANE || !reglages.LIBELLE_TRAITE_ID)) {
  throw new Error('Mode réel sans ADRESSE_PENNYLANE ou LIBELLE_TRAITE_ID : renseigner Réglages · WF1.');
}
return [{ json: { reglages } }];

// Un élément par PDF joint : Pennylane reçoit un document par mail.
// Logos, signatures et autres images sont écartés ; un mail sans PDF ne produit rien.
const sorties = [];
$input.all().forEach((item, index) => {
  const mail = item.json || {};
  if (!mail.id) return;
  const expediteur = (mail.from && mail.from.text) || '';
  Object.entries(item.binary || {}).forEach(([cle, fichier]) => {
    const nom = String(fichier.fileName || cle);
    const estPdf = fichier.mimeType === 'application/pdf' || nom.toLowerCase().endsWith('.pdf');
    if (!estPdf) return;
    sorties.push({
      json: {
        messageId: mail.id,
        expediteur,
        objet: mail.subject || '',
        recuLe: mail.date || '',
        fichier: nom,
      },
      binary: { data: fichier },
      pairedItem: { item: index },
    });
  });
});
return sorties;

