// Le libellé se pose une fois par mail, même quand il portait plusieurs PDF.
const vus = new Set();
return $('Gmail – une pièce jointe PDF par envoi').all()
  .filter(i => !vus.has(i.json.messageId) && vus.add(i.json.messageId))
  .map(i => ({ json: { messageId: i.json.messageId } }));
